 if(!p.readonly&&(!['weapon2','quiver2'].includes(slot)||independent)&&finish?.alternatives?.length)main+=expand('没有首选材料时怎么替代？',finish.alternatives.map(x=>`<p>${esc(x)}</p>`).join(''));
