function skillName(id){return D.gems[id]?.zh||id.split('/').pop()}
function skillSetup(s){
 if(phase().readonly)return ['只读原件','不据此配置武器组'];
 const n=skillName(s.id);if(n==='冰冻印记')return ['武器组Ⅱ','作者正文分组；施放后检查切回'];
 if(['冰霜射击','狙击','龙卷射击','冰尖箭矢','弹幕'].includes(n))return ['武器组Ⅰ','作者正文的输出组'];
 if(/AscendancyMirageDeadeye/.test(s.id))return ['升华元技能','先取得蜃影神射升华，再配置内嵌主动与辅助'];
 if(/MirageArcher/.test(s.id))return ['元技能','单独核对精魂与内嵌技能，不当作普通辅助'];
 return ['常驻／功能','检查开启状态与两组资源；正文未逐项指定武器组'];
}
