 main+=sec('char-skills','02','技能与辅助组合',`${!b.ascendancyConflict?`<div class="skill-setup-brief"><p><b>缺孔：</b>${esc(D.skillSetupNotes.links)}</p><p><b>辅助阶别：</b>${esc(D.skillSetupNotes.mandatory)}</p></div>`:''}<div class="panel"><table class="skill-table"><thead><tr><th>技能</th><th>辅助组合 · 当前分支完整记录</th><th>连接结构</th><th>武器组／生效条件</th></tr></thead><tbody>${skillRows.join('')}</tbody></table></div><div class="caption">${icon('info',12)}原件的 31–100 等区间是角色显示区间，不是宝石等级。宝石本体等级和品质未统一指定，不代填。</div>`,'<p>主动技能与内嵌技能明确区分</p>');
