function searchData(q){let data=[{title:'过滤器：选择、下载与01补底材碎片',text:'01/02/03/04 · 原版与补充版分清',route:'tools/filters',query:'过滤器 自用版 补材料 底材 碎片 富豪碎片 巧匠碎片 开荒 剧情'}, {title:'过滤器完整颜色图例',text:'文字 底色 边框 光柱 地图图标 声音',route:'filter-guide',query:'过滤器 提示 底色 蓝底 青绿 深红 声音 光柱 颜色 边框'}, {title:'物品显示与隐藏判断',text:'按区域、物等、品质、孔位计算匹配链',route:'filter-check',query:'过滤器 显示 隐藏 门票 巨灵币 磨刀石 金币 不显示 5000'},...Object.values(D.learningPages).map(x=>({title:x.title,text:'R37 成长与规则 / '+x.summary,route:'learn/'+x.id,query:x.search+' '+x.sections.map(s=>s.title+' '+s.html.replace(/<[^>]+>/g,' ')).join(' ')})),{title:'新手异界开荒 · Lazy Exile',text:'异界与刷图 / 主树起步、任务推进与三张原图',route:'atlas-starter',query:D.atlasStarter.search},...D.stages.flatMap(p=>p.items.filter(i=>!i.utility).map(i=>({title:i.title+' · '+i.name,text:p.label+' / 装备目标与打造',route:'item/'+i.uid,params:{stage:p.id},query:i.records?.[0]?.en||''}))),...D.variants.map(v=>({title:v.zh,text:v.name+' / Fubgun 异界方案',route:'atlas/'+v.id,query:D.atlasRecords[v.id].search_text})),...D.documents.map(d=>({title:d.title,text:d.group+' / 完整详稿',route:'reference',params:{doc:d.file},query:d.keywords||''})),...Object.entries(D.materials).map(([k,v])=>({title:v.zh,text:v.en+' / 材料与作用',route:'tools/dictionary',params:{q:v.zh}})),...D.augments.map(v=>({title:v.name,text:v.en+' / 强化材料',route:'tools/dictionary',params:{q:v.name}})),{title:'技能组合与宝石升级',text:'人物与技能 / 当前阶段',route:'character',params:{stage:state.stage}},{title:'异界解锁顺序',text:'异界与刷图 / 进入异界',route:'atlas-unlock'},{title:'七套方案怎么选',text:'地图、碑牌、适用条件与配套对照',route:'atlas-choose'}];if(!q)return [data[0],data.find(d=>d.title==='技能组合与宝石升级'),...data.filter(d=>d.route.startsWith('atlas/')).slice(0,4)];q=q.toLowerCase();let seen=new Set();return data.filter(d=>(d.title+' '+d.text+' '+(d.query||'')).toLowerCase().includes(q)).filter(d=>{let k=d.title+d.text;if(seen.has(k))return false;seen.add(k);return true}).slice(0,18)}
