function atlasStarter(){return (note('第一次实际开图，先看 '+routeLink('learn/map-run','地图准备、完成、失败与下一轮')+'；下方是主树推进路线。')+atlasStarterBase()).replace('<div class="content-with-toc',`<div class="learning-bridge"><div><strong>进异界之前，也检查人物永久成长</strong><p class="small muted">升华点、任务精魂、常驻技能与试炼不是同一套系统。</p></div><div class="actions">${routeLink('learn/ascendancy','升华点获取','btn small')}${routeLink('learn/permanent','永久奖励','btn small')}${routeLink('learn/activities','其他试炼','btn small')}</div></div><div class="content-with-toc`);}

// R37: all source-defined modifiers, named completion choices and explicit route end state.
function targetData(slot){return D.equipmentTargets?.[state.stage]?.[slot]||null}
function modRows(rows){return rows.map((r,i)=>`<tr data-target-kind="${esc(r.kind)}"><td class="mod-index">${String(i+1).padStart(2,'0')}</td><td><strong>${esc(r.text)}</strong></td><td><span class="target-origin">${esc(r.kind)}</span><div class="small muted">${esc(r.detail)}</div></td></tr>`).join('')}
function modTable(rows){return `<div class="table-scroll"><table class="modifier-table"><thead><tr><th>项</th><th>装备应有的词缀／效果</th><th>要求与来源</th></tr></thead><tbody>${modRows(rows)}</tbody></table></div>`}
function fullTargetPanel(it,slot){const t=targetData(slot),f=finishPlan(slot);if(!t)return note('没有独立原件记录，不能复制其他装备的词缀。',true);
 let body=`<div class="panel complete-target"><div class="complete-target-head"><div><span class="tag">成品属性清单</span><h3>${esc(t.title)}</h3></div><button class="btn small" data-scroll="item-craft">看如何做出来 ${icon('arrow',12)}</button></div>`;
 if(t.implicit)body+=`<div class="modifier-implicit"><b>底材固有属性：</b>${esc(t.implicit)}<span class="sub">与下方加工词缀分开；不重复占用同一个计数。</span></div>`;
 if(t.raw.length){body+=`<div class="mod-section-label">作者原件已写明的全部属性 <span>${t.raw.length} 项原始描述，不用行数推算前后缀</span></div>`+modTable(t.raw);}
 else if(!t.definitions.length)body+=`<div class="modifier-missing">${slot==='jewels'?'作者没有逐颗珠宝实装；下面按正文列明要找的具体词缀。':(['weapon2','quiver2'].includes(slot)?'原件未单独列这件副装备。不复制主手，也不安排一份假成品。':'原件仅给名称，未提供具体数值词条。')}</div>`;
 if(t.definitions.length)body+=`<div class="mod-section-label">此暗金的完整功能与数值范围 <span>游戏数据补充 · 不是作者实际掷值</span></div>`+modTable(t.definitions);
 if(t.mechanicChoices?.length)body+=`<div class="mod-section-label">六种随机箭矢具体是什么 <span>每支箭只抽到其中一种；下方为功能中文说明</span></div><div class="table-scroll"><table class="modifier-table"><tbody>${t.mechanicChoices.map((x,i)=>`<tr><td>${i+1}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.text)}</td></tr>`).join('')}</tbody></table></div>`;
 if(t.supplement.length)body+=`<div class="mod-section-label">还要补什么／可以换成什么 <span>可选项目不能全部叠成“必需六条”</span></div>`+modTable(t.supplement);
 body+=`<div class="target-bottom"><b>做到什么算够用：</b>${esc(t.closing)}</div></div>`;
 if(!t.readonly&&!t.unique&&!['weapon2','quiver2','jewels','life_flask','mana_flask','charm1','charm2','charm3'].includes(slot))body+=`<div class="whole-set-note"><b>抗性和装备给予的属性怎么分配：</b>整套火焰、冰霜、闪电抗性各补到75%；缺智慧时在一枚戒指或项链解决，力量优先看腰带。余下合法空位再考虑混沌抗性。这里的“补属性”已拆成具体词条，不是佩戴需求。<span class="small muted">作者没有固定每个部位各补多少，不按想象填写三条满值抗性。</span></div>`;
 let wearing=(it?.wear?`<p>使用等级：${it.wear.level||'未提供'}；需要 ${esc(wearText(it.wear))}。这是佩戴要求，不是该装备给予的词缀。</p>`:'<p>佩戴要求以实际物品为准，原件没有提供的值不补猜。</p>');
 body+=expand('佩戴条件、孔位、取得方式与原件出处',wearing+`<p>普通增幅孔：${f?.cap||'不适用'}。${esc(it?.acquire||f?.why||'按实际配置检查。')}</p><p>${esc(it?.alternative||'')}</p><p>原件：${esc(t.sourceFile||'未单独提供')}。</p>`+(t.raw.length?safeLink(it?.sourceUrl||D.equipmentTargetAudit.source,'作者说明'):''));
 const sources=[...new Set([...t.definitions,...t.supplement,...(t.mechanicChoices||[])].map(x=>x.url).filter(Boolean))];if(sources.length)body+=expand('补充属性的出处',sources.map(u=>safeLink(u,u.includes('poe2db')?'物品数据定义':'作者装备说明')).join('　')+'<p class="small muted">原始构筑文件未修改。中文为阅读转述；属性范围与加工目标分开，不把来源未定的数值填满。</p>');
 return body;
}
function routeEndState(r,slot,isAlternate=false){if(!r)return '';
 const t=targetData(slot);const st=r.steps||[];const possible=st.filter(x=>['finish','good','done'].includes(x.id)).flatMap(x=>x.expect||[]);
 const stageLine=isAlternate?'这是普通／稀有替代品，目标不等于上方暗金的效果。':'上方是本阶段完整目标；下面说明这条工艺能控制到哪里。';
 const random=/随机|random|崇高|最后两|后缀/.test(JSON.stringify(st));
 let modline='';
 if(!isAlternate&&t?.raw?.length)modline=`<div class="route-result-mods"><b>加工时对照的原件属性：</b>${t.raw.map(x=>esc(x.text)).join('；')}。</div>`;
 if(isAlternate){const key=slot==='quiver'?'quiver':slot==='belt'?'belt':slot==='mana_flask'?'mana_flask':slot;
 const base=D.equipmentTargets?.e01?.[key];if(base?.raw?.length)modline=`<div class="route-result-mods"><b>普通替代品参考属性（起步原件）：</b>${base.raw.map(x=>esc(x.text)).join('；')}。${base.supplement?.length?'补位候选：'+base.supplement.map(x=>esc(x.text)).join('；')+'。':''}</div>`;
 }
 return `<div class="panel recipe-destination"><div class="mod-section-label">先确认这条工艺的终点 <span>${stageLine}</span></div><p><b>期望得到：</b>${esc(r.goal||'以原工艺的完成条件为准')}</p>${modline}<p class="small"><b>不要误解：</b>${random?'步骤能保证的结果，以每步的“结果／继续条件”为准；随机加词缀不保证把目标清单全部做出来。已经有足够有效属性，可以停手，不强迫做满。':'这条路线只处理它写明的目标；未列出的属性不能算作完成后必得。'}</p></div>`;
}
function gearModifierCell(it){const t=targetData(it.uid);if(!t)return fullModLine(it);const rows=t.raw.length?t.raw:t.definitions;let s=rows.map(x=>`<div class="gear-mod">${esc(shortMod(x.text))}</div>`).join('')||'<span class="small muted">未有完整实装词条</span>';if(t.supplement.length)s+=`<div class="gear-mod-extra"><b>补位：</b>${t.supplement.map(x=>esc(x.text)).join('；')}</div>`;if(t.unique)s+='<span class="sub">暗金定义／范围在详情，不套普通黄装工艺</span>';return s;}
function ascendancyChinese(){const a=D.chineseAscendancy;let main='';
 main+=`<div class="asc-intro"><strong>总共8点，分四次获得，每次新增2点。</strong><p>不是人物升级自动给，也不是每次分别送2、4、6、8点。已经有4点，就直接看“第三次”。</p></div>`;
 main+=`<div class="ascendancy-picker panel panel-inner"><strong>现在已有多少点？</strong><span class="small muted">已用点＋未分配点的合计；按钮只定位下一次。</span><div class="actions" role="group" aria-label="已获得升华点">${[0,2,4,6,8].map(n=>`<button class="btn" data-earned="${n}" aria-pressed="${getStore('earned-ascendancy','0')===String(n)}">${n===0?'还没升华':n===8?'已经8点':'已有'+n+'点'}</button>`).join('')}</div><p id="ascendancy-next" role="status"></p></div>`;
 main+=`<p class="caption">先用丝克玛讲完整条路线，混沌替代放在后面。门票上的区域等级不是人物等级；层数指要完成的整层，不是几个房间。这是阅读安排，不是作者指定的唯一路线。</p>`;
 for(const [i,x] of a.steps.entries())main+=sec('asc-stage-'+x.from,'0'+(i+1),esc(x.title),`<div class="panel asc-stage" data-asc-card="${x.from}"><div class="asc-stage-top"><span class="asc-count">${x.from} → ${x.to} 点</span><div><strong>${esc(x.location)}</strong><p><b>门票：</b>${esc(x.ticket)}</p></div></div><div class="asc-actions"><div><span>拿票</span><p>${esc(x.get)}</p></div><div><span>通关</span><p>${esc(x.do)}</p></div><div class="asc-claim"><span>领点</span><p>${esc(x.claim)}</p></div><div><span>加点</span><p>${esc(x.build)}</p></div></div><p class="asc-tip">${esc(x.tip)}</p></div>`,'',i===0);
 main+=sec('asc-chaos','05','更想打混沌试炼？只换获取方式',`<div class="panel asc-alternative"><p><b>入口：</b>第三章“幻缈湿地”击败“奇美拉赛克鲁西安”，取得任务门票“幻缈贪婪战书”；进入“混沌大殿”，在供奉装置放入门票。普通进阶门票叫“贪婪战书”。</p><div class="table-scroll"><table class="audit-table"><thead><tr><th>你现在有</th><th>需要的门票／挑战</th><th>这次怎么拿点</th></tr></thead><tbody><tr><td>0点</td><td>可授予首次升华的4房试炼</td><td>完成要求的房间和首领后，使用升华祭坛，选择锐眼，增加2点。</td></tr><tr><td>2点</td><td>先看第三章任务票是否标注还能授予升华点；普通票则需7房、区域等级至少55</td><td>完成对应一轮并使用升华祭坛，增加2点，达到4点。不能把任意普通4房票当作第二次的票。</td></tr><tr><td>4点</td><td>10房、区域等级至少65的普通贪婪战书</td><td>完成十房并使用升华祭坛，增加2点，达到6点。</td></tr><tr><td>6点</td><td>完成能够到达试炼大师入口的一轮；备齐“懦弱的命运”“危难的命运”“胜利的命运”各1份</td><td>在末端提交三种不同碎片，击败试炼大师并领取最后2点。只再打十房不等于自动拿满8点。</td></tr></tbody></table></div><p>门票条件看<strong>区域等级、房数和当前角色的升华资格提示</strong>，不是人物等级。已经拿过某一组，无论从哪种试炼再拿同一组，都不会重复加点。</p><p>0.5.5可以逐房领奖并续跑十房后的两轮；但已有三种命运碎片时，不必为了最后两点强行同一次连跑三十房。</p><div class="actions">${routeLink('learn/chaos','混沌房间与负面怎么选','btn')}${routeLink('learn/sekhemas','丝克玛荣誉与房间怎么走','btn')}</div></div>`);
 main+=sec('asc-check','06','打完没有加点，按这三项查',`<div class="panel asc-check"><p><b>① 门票够不够：</b>它是否还能给你下一组点？已有6点，再用三层巨灵币不会给最后两点。</p><p><b>② 深度到没到：</b>三层需要完成到第三层，不是只过三个房间；一张四层票只打第一层也不算四层完成。</p><p><b>③ 祭坛点没点：</b>进入奖励区使用升华祭坛。奖励箱、地上战利品和升华点不是同一个领取动作。</p><p><b>8点以后：</b>再跑试炼是为了奖励或重选升华，不会获得第10点。想改升华，需完成有资格的试炼并清空旧升华点，不能直接更换人物基础职业。</p></div>`);
 main+=expand('中文名字、原文对照与来源',`<p>${esc(a.basis)} 默认阅读无需识别英文；下面只给外服查词用。</p><div class="table-scroll"><table class="audit-table"><thead><tr><th>中文</th><th>外服对照</th></tr></thead><tbody>${a.aliases.map(r=>`<tr><td>${esc(r[0])}</td><td>${esc(r[1])}</td></tr>`).join('')}</tbody></table></div><div class="asc-source-list">${a.sources.map(([n,u])=>safeLink(u,esc(n))).join('')}</div>`);
 return heading('人物与技能 / 升华获取','升华点怎么拿','每次只看一条路线：去哪 → 拿票 → 通关 → 在祭坛领2点。')+`<div class="content-with-toc learning-page asc-cn"><div>${main}</div>${toc(a.steps.map((x,i)=>['asc-stage-'+x.from,'0'+(i+1),x.from+' → '+x.to+' 点']).concat([['asc-chaos','05','混沌替代'],['asc-check','06','没加点怎么查']]))}</div>`+footer();
}
